#!/usr/bin/env bash
# Sample SQL Server TPG source for the `dev` profile (US-114): synthetic data only, never client data.
# Runs once from the sample-mssql-seed job: creates database tpg, loads 02-data.sql (generated by
# deploy/compose/dev-setup.sh) and a login tela_ro in db_datareader only (RULE-001).
set -euo pipefail
sa_pw="$(cat /run/secrets/sample_mssql_sa_password)"
ro_pw="$(cat /run/secrets/sample_mssql_ro_password)"
sql() { /opt/mssql-tools18/bin/sqlcmd -C -b -S sample-mssql -U sa -P "$sa_pw" "$@"; }
for _ in $(seq 1 60); do sql -Q "SELECT 1" >/dev/null 2>&1 && break; sleep 2; done
sql -Q "IF DB_ID('tpg') IS NULL CREATE DATABASE tpg"
if [[ "$(sql -d tpg -h -1 -W -Q "SET NOCOUNT ON; SELECT count(*) FROM sys.tables WHERE name = 'projects'")" == "0" ]]; then
  sql -d tpg -i /seed/02-data.sql >/dev/null
fi
sql -v ro_pw="$ro_pw" -Q "IF SUSER_ID('tela_ro') IS NULL CREATE LOGIN tela_ro WITH PASSWORD = '\$(ro_pw)'"
sql -d tpg -Q "IF USER_ID('tela_ro') IS NULL CREATE USER tela_ro FOR LOGIN tela_ro; ALTER ROLE db_datareader ADD MEMBER tela_ro"
# The Dataverse TDS stand-in (US-110, development only): the same extract under Dataverse logical names.
sql -Q "IF DB_ID('tpg_dataverse') IS NULL CREATE DATABASE tpg_dataverse"
if [[ "$(sql -d tpg_dataverse -h -1 -W -Q "SET NOCOUNT ON; SELECT count(*) FROM sys.tables WHERE name = 'tpg_project'")" == "0" ]]; then
  sql -d tpg_dataverse -i /seed/03-dataverse.sql >/dev/null
fi
sql -d tpg_dataverse -Q "IF USER_ID('tela_ro') IS NULL CREATE USER tela_ro FOR LOGIN tela_ro; ALTER ROLE db_datareader ADD MEMBER tela_ro"
echo "sample-mssql seeded"
